CREATE OR REPLACE FUNCTION public.adjust_order_credit(p_kind text,p_order uuid,p_limit numeric) RETURNS numeric LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o record; v_new numeric; BEGIN IF p_limit IS NULL OR p_limit<0 THEN RAISE EXCEPTION 'Importe inválido'; END IF; IF p_kind='store' THEN SELECT cliente_id,credito_aplicado,stripe_environment,estado,monto_capturado INTO o FROM store_orders WHERE id=p_order FOR UPDATE; ELSIF p_kind='cookie' THEN SELECT cliente_id,credito_aplicado,stripe_environment,estado,monto_capturado INTO o FROM pedidos WHERE id=p_order FOR UPDATE; ELSE RAISE EXCEPTION 'Origen inválido'; END IF; IF o.cliente_id IS NULL THEN RAISE EXCEPTION 'Pedido no disponible'; END IF; IF COALESCE(o.monto_capturado,0)>0 THEN RETURN o.credito_aplicado; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(o.cliente_id::text||':'||o.stripe_environment,0)); v_new:=LEAST(COALESCE(o.credito_aplicado,0),round(p_limit,2)); IF v_new<COALESCE(o.credito_aplicado,0) THEN INSERT INTO wallet_credits(user_id,amount_usd,reason,order_id,order_kind,stripe_environment,operation_key) VALUES(o.cliente_id,o.credito_aplicado-v_new,'devolucion_saldo',p_order,p_kind,o.stripe_environment,'adjust:'||p_kind||':'||p_order||':'||v_new) ON CONFLICT(operation_key) WHERE operation_key IS NOT NULL DO NOTHING; IF p_kind='store' THEN UPDATE store_orders SET credito_aplicado=v_new WHERE id=p_order; ELSE UPDATE pedidos SET credito_aplicado=v_new WHERE id=p_order; END IF; END IF; RETURN v_new; END $$;
REVOKE ALL ON FUNCTION public.adjust_order_credit(text,uuid,numeric) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.adjust_order_credit(text,uuid,numeric) TO service_role;
CREATE OR REPLACE FUNCTION public.release_order_credit(p_kind text,p_order uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w record; o record; v_adjust numeric; BEGIN IF p_kind NOT IN ('store','cookie') THEN RAISE EXCEPTION 'Origen inválido'; END IF; SELECT * INTO w FROM wallet_credits WHERE operation_key='reserve:'||p_kind||':'||p_order; IF NOT FOUND THEN RETURN; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(w.user_id::text||':'||w.stripe_environment,0)); IF p_kind='store' THEN SELECT estado,monto_capturado INTO o FROM store_orders WHERE id=p_order; ELSE SELECT estado,monto_capturado INTO o FROM pedidos WHERE id=p_order; END IF; IF o.estado IS DISTINCT FROM 'cancelado' OR COALESCE(o.monto_capturado,0)>0 THEN RAISE EXCEPTION 'Solo se devuelve saldo de pedidos cancelados sin cobro'; END IF; SELECT COALESCE(SUM(amount_usd),0) INTO v_adjust FROM wallet_credits WHERE order_id=p_order AND order_kind=p_kind AND operation_key LIKE 'adjust:'||p_kind||':'||p_order||':%'; INSERT INTO wallet_credits(user_id,amount_usd,reason,order_id,order_kind,stripe_environment,operation_key) VALUES(w.user_id,GREATEST(0,-w.amount_usd-v_adjust),'devolucion_saldo',p_order,p_kind,w.stripe_environment,'release:'||p_kind||':'||p_order) ON CONFLICT(operation_key) WHERE operation_key IS NOT NULL DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.release_order_credit(text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.release_order_credit(text,uuid) TO service_role;